import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, vec2, fract, sin, dot, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, PlaneGeometry, Mesh, DoubleSide, SRGBColorSpace, Color } = THREE;

  const root = new Group();
  const timelines = [];
  root.userData.timelines = timelines;
  root.userData.handlers = {};
  root.userData.isCleaned = false;

  const specColors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new Color(specColors.ink ?? '#16161d');
  const surface = new Color(specColors.surface ?? '#0b0b10');

  const u = uv();
  const gradient = mix(color(ink), color(surface), smoothstep(0, 1, u.y));
  const grainUv = u.mul(240);
  const grain = fract(sin(dot(grainUv, vec2(12.9898, 78.233))).mul(43758.5453)).sub(0.5).mul(0.035);
  const bgColorNode = gradient.add(grain);

  const bgMat = new MeshBasicNodeMaterial({ colorNode: bgColorNode, side: DoubleSide });
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  root.add(bgMesh);

  const region = config.atlasRegion ?? config.intent?.visualSpec?.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const rx = region.x ?? region.left ?? 0;
  const ry = region.y ?? region.top ?? 0;
  const rw = region.w ?? region.width ?? 512;
  const rh = region.h ?? region.height ?? 320;
  const aspect = rw / rh;

  const baseHeight = 3.2;
  const spriteGeo = new PlaneGeometry(aspect * baseHeight, baseHeight);
  const spriteMat = new MeshBasicNodeMaterial({ transparent: true, alphaTest: 0.01, side: DoubleSide });
  const spriteMesh = new Mesh(spriteGeo, spriteMat);
  spriteMesh.visible = false;
  root.add(spriteMesh);

  root.userData.handlers.onBeforeRender = () => {
    spriteMesh.quaternion.copy(ctx.camera?.quaternion ?? root.parent?.parent?.parent?.parent?.parent?.parent?.parent?.parent?.parent?.parent);
  };

  spriteMesh.onBeforeRender = (renderer, scene, camera, geometry, material, group) => {
    root.userData.handlers.onBeforeRender(renderer, scene, camera, geometry, material, group);
  };

  let loadedTexture = null;

  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    const apply = ctx.primitives?.[p.name];
    if (typeof apply === 'function') {
      const result = apply(root, p.params ?? {});
      if (result?.timeline) timelines.push(result.timeline);
    }
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (root.userData.isCleaned) return;
      loadedTexture = tex;
      tex.colorSpace = SRGBColorSpace;

      const imgW = tex.image?.width || rw;
      const imgH = tex.image?.height || rh;
      tex.repeat.set(rw / imgW, rh / imgH);
      tex.offset.set(rx / imgW, 1 - (ry + rh) / imgH);
      tex.needsUpdate = true;

      spriteMat.map = texture(tex);
      spriteMat.needsUpdate = true;
      spriteMesh.visible = true;
    }).catch(() => {
      spriteMesh.visible = false;
    });
  }

  root.userData.cleanup = () => {
    root.userData.isCleaned = true;
    timelines.forEach((t) => { try { t?.kill(); } catch (e) {} });
    spriteMesh.onBeforeRender = null;
    if (loadedTexture) loadedTexture.dispose();
    spriteMat.dispose();
    spriteGeo.dispose();
    bgMat.dispose();
    bgGeo.dispose();
  };

  return root;
}
